import Box from '@mui/material/Box';
import { useDefaultProps } from '@mui/material/DefaultPropsProvider';
import FormControl, { type FormControlProps } from '@mui/material/FormControl';
import FormHelperText, { type FormHelperTextProps } from '@mui/material/FormHelperText';
import InputLabel, { type InputLabelProps } from '@mui/material/InputLabel';
import OutlinedInput, { type OutlinedInputProps } from '@mui/material/OutlinedInput';
import type { TextFieldClasses, TextFieldOwnerState, TextFieldProps } from '@mui/material/TextField';
import { useForkRef } from '@mui/material/utils';
import clsx from 'clsx';
import { mergeSx } from 'merge-sx';
import { forwardRef, useId, type InputHTMLAttributes, type ReactNode, type RefAttributes } from 'react';

import { fieldHelperStyles, fieldInputStyles, fieldLabelStyles, fieldRootStyles } from './sv-field.styles.ts';

type MuiFieldProps = TextFieldProps<'outlined'>;
export type SvFieldClasses = TextFieldClasses;
export interface SvFieldOwnerState extends TextFieldOwnerState {
  disabled: boolean;
  error: boolean;
  required: boolean;
  fullWidth: boolean;
  multiline: boolean;
  variant: 'outlined';
}
export interface SvFieldProps extends Omit<MuiFieldProps, 'variant' | 'select' | 'children' | 'slots' | 'slotProps'> {
  variant?: 'outlined';
  slots?: Omit<NonNullable<MuiFieldProps['slots']>, 'select'>;
  slotProps?: Omit<NonNullable<MuiFieldProps['slotProps']>, 'select'>;
  labelAdornment?: ReactNode | ((ownerState: SvFieldOwnerState) => ReactNode);
  headerAction?: ReactNode | ((ownerState: SvFieldOwnerState) => ReactNode);
}

declare module '@mui/material/styles' {
  interface ComponentsPropsList {
    SvField: SvFieldProps;
  }
  interface Components {
    SvField?: { defaultProps?: Partial<SvFieldProps> | undefined } | undefined;
  }
}

/** Resolve a public MUI slot callback without using private MUI hooks. */
export function resolveFieldSlot<T, S>(slot: T | ((state: S) => T) | undefined, state: S): T | undefined {
  return typeof slot === 'function' ? (slot as (state: S) => T)(state) : slot;
}

export const SvField = forwardRef<HTMLDivElement, SvFieldProps>(function SvField(inProps, ref) {
  const muiDefaults = useDefaultProps<SvFieldProps>({
    props: {},
    name: 'MuiTextField',
  });
  const svDefaults = useDefaultProps<SvFieldProps>({
    props: {},
    name: 'SvField',
  });
  const svProps = useDefaultProps({ props: inProps, name: 'SvField' });
  const props = useDefaultProps({ props: svProps, name: 'MuiTextField' });
  const {
    label,
    helperText,
    labelAdornment,
    headerAction,
    id: suppliedId,
    disabled = false,
    error = false,
    required = false,
    fullWidth = false,
    multiline = false,
    variant = 'outlined',
    color = 'primary',
    size = 'medium',
    value,
    defaultValue,
    onChange,
    onFocus,
    onBlur,
    inputRef,
    name,
    type,
    autoComplete,
    autoFocus,
    placeholder,
    rows,
    minRows,
    maxRows,
    sx,
    className,
    classes,
    slots = {},
    slotProps = {},
    ...other
  } = props;
  const ownerState: SvFieldOwnerState = {
    ...props,
    disabled,
    error,
    required,
    fullWidth,
    multiline,
    variant,
    color,
    size,
  };
  const rootProps = resolveFieldSlot(slotProps.root, ownerState) as FormControlProps | undefined;
  const inputProps = resolveFieldSlot(slotProps.input, ownerState) as OutlinedInputProps | undefined;
  const htmlProps = resolveFieldSlot(slotProps.htmlInput, ownerState) as
    | (InputHTMLAttributes<HTMLInputElement> & RefAttributes<HTMLInputElement>)
    | undefined;
  const legacyHtmlProps = inputProps?.inputProps as
    | (InputHTMLAttributes<HTMLInputElement> & RefAttributes<HTMLInputElement>)
    | undefined;
  const labelProps = resolveFieldSlot(slotProps.inputLabel, ownerState) as InputLabelProps | undefined;
  const helperProps = resolveFieldSlot(slotProps.formHelperText, ownerState) as FormHelperTextProps | undefined;
  const generatedId = useId();
  const id = htmlProps?.id ?? inputProps?.id ?? suppliedId ?? generatedId;
  const hasHelper = helperText != null && helperText !== false && helperText !== '';
  const helperId = hasHelper ? (helperProps?.id ?? `${id}-helper-text`) : undefined;
  const rootRef = useForkRef(ref, rootProps?.ref);
  const nativeRef = useForkRef(inputRef, inputProps?.inputRef);
  const Root = slots.root ?? FormControl;
  const Input = slots.input ?? OutlinedInput;
  const Label = slots.inputLabel ?? InputLabel;
  const Helper = slots.formHelperText ?? FormHelperText;
  const adornment = typeof labelAdornment === 'function' ? labelAdornment(ownerState) : labelAdornment;
  const action = typeof headerAction === 'function' ? headerAction(ownerState) : headerAction;
  const describedBy =
    [
      ...new Set(
        clsx(
          helperId,
          other['aria-describedby'],
          inputProps?.['aria-describedby'],
          legacyHtmlProps?.['aria-describedby'],
          htmlProps?.['aria-describedby']
        )
          .split(' ')
          .filter(Boolean)
      ),
    ].join(' ') || undefined;
  return (
    <Root
      {...(typeof Root !== 'string' && { ownerState })}
      {...other}
      disabled={disabled}
      error={error}
      required={required}
      fullWidth={fullWidth}
      variant={variant}
      color={color}
      size={size}
      {...rootProps}
      ref={rootRef}
      className={clsx('SvField-root', classes?.root, className, rootProps?.className)}
      sx={mergeSx(fieldRootStyles, muiDefaults.sx, svDefaults.sx, sx, rootProps?.sx)}
    >
      {((label != null && label !== '') || adornment != null || action != null) && (
        <Box
          className="SvField-header"
          sx={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: '8px',
            minWidth: 0,
          }}
        >
          <Box
            sx={{
              display: 'flex',
              alignItems: 'center',
              gap: '4px',
              minWidth: 0,
              flex: 1,
            }}
          >
            {label != null && label !== '' && (
              <Label
                {...(typeof Label !== 'string' && { ownerState })}
                shrink={false}
                disableAnimation
                {...labelProps}
                htmlFor={id}
                className={clsx('SvField-label', labelProps?.className)}
                sx={mergeSx(fieldLabelStyles, labelProps?.sx)}
              >
                {label}
              </Label>
            )}
            {adornment}
          </Box>
          {action != null && (
            <Box className="SvField-headerAction" sx={{ display: 'flex', flexShrink: 0 }}>
              {action}
            </Box>
          )}
        </Box>
      )}
      <Input
        {...(typeof Input !== 'string' && { ownerState })}
        value={value}
        defaultValue={defaultValue}
        onChange={onChange}
        onFocus={onFocus}
        onBlur={onBlur}
        name={name}
        type={type}
        autoComplete={autoComplete}
        autoFocus={autoFocus}
        placeholder={placeholder}
        multiline={multiline}
        rows={rows}
        minRows={minRows}
        maxRows={maxRows}
        fullWidth={fullWidth}
        notched={false}
        {...inputProps}
        id={id}
        inputRef={nativeRef}
        slots={{
          ...inputProps?.slots,
          ...(slots.htmlInput && { input: slots.htmlInput }),
        }}
        inputProps={{
          ...legacyHtmlProps,
          ...htmlProps,
          id,
          'aria-describedby': describedBy,
        }}
        className={clsx('SvField-input', inputProps?.className)}
        sx={mergeSx(fieldInputStyles, inputProps?.sx, inputProps?.slotProps?.root?.sx)}
      />
      {hasHelper && (
        <Helper
          {...(typeof Helper !== 'string' && { ownerState })}
          {...helperProps}
          id={helperId}
          className={clsx('SvField-helperText', helperProps?.className)}
          sx={mergeSx(fieldHelperStyles, helperProps?.sx)}
        >
          {helperText}
        </Helper>
      )}
    </Root>
  );
});
